contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address staker, uint256 depositAmount, bool claim) public {
        require(depositAmount > 0, "amount must be positive");

        c.stakeFor(staker, depositAmount);

        uint256 beforeBalance = c.balanceOf(staker);
        uint256 beforeTotalSupply = c.totalSupply();
        uint256 beforeC = address(c).balance;
        uint256 beforeThis = address(this).balance;

        bool reverted;
        try c.withdrawAll(claim) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBalance = c.balanceOf(staker);
        uint256 afterTotalSupply = c.totalSupply();
        uint256 afterC = address(c).balance;
        uint256 afterThis = address(this).balance;

        assert(
            reverted ||
            (beforeBalance == depositAmount &&
             afterBalance == 0 &&
             beforeTotalSupply - afterTotalSupply == beforeBalance &&
             afterThis - beforeThis == beforeBalance &&
             beforeC - afterC == beforeBalance)
        );
    }

    receive() external payable {}
}

