contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address token) public payable {
        require(token != address(0), "zero token");

        uint256 beforeLen = c.rewardTokens.length();
        uint40 beforeLastUpdate = c.rewardPeriodFinish(token);

        bool reverted;
        try c.addReward(token) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(beforeLen == 0 && c.rewardTokens.length() == 1 && c.rewardTokens(0) == token && c.rewardPeriodFinish(token) > 0);
        } else {
            assert(c.rewardTokens.length() == beforeLen && c.rewardPeriodFinish(token) == beforeLastUpdate);
        }
    }

    receive() external payable {}
}

