        if (!reverted) {
            assert(!beforeAdded && c.rewardTokens.length == beforeLen + 1 && c.rewardTokens(beforeLen) == token && c.rewardPeriodFinish(token) > 0);
        } else {
            assert(c.rewardTokens.length == beforeLen && (c.rewardPeriodFinish(token) > 0) == beforeAdded);
        }
    }

