}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address token) public payable {
        require(token != address(0), "zero token");

        bool beforeAdded = c.rewardPeriodFinish(token) > 0;
        uint256 beforeLen = 0;
        {
            bool keep = true;
            while (keep) {
                (bool ok, bytes memory data) = address(c).staticcall(abi.encodeWithSignature("rewardTokens(uint256)", beforeLen));
                if (!ok || data.length < 32) { keep = false; }
                else { beforeLen += 1; }
            }
        }

        bool reverted;
        try c.addReward(token) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            (bool ok, bytes memory data) = address(c).staticcall(abi.encodeWithSignature("rewardTokens(uint256)", beforeLen));
            address added = ok && data.length >= 32 ? abi.decode(data, (address)) : address(0);
            assert(!beforeAdded && added == token && c.rewardPeriodFinish(token) > 0);
        } else {
            assert(beforeAdded == (c.rewardPeriodFinish(token) > 0));
        }
    }

    receive() external payable {}
}

