contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public payable {
        amount = amount % 1e30;
        require(amount > 0, "amount must be positive");
        require(c.balanceOf(address(this)) == 0, "fresh contract has no balance");
        require(c.totalSupply() == 0, "fresh contract has no supply");

        address token = address(c.stakingToken());
        (bool ok, bytes memory data) = token.call(abi.encodeWithSignature("balanceOf(address)", address(this)));
        require(ok && data.length >= 32, "token balance read failed");
        uint256 tokenBalance = abi.decode(data, (uint256));
        require(tokenBalance >= amount, "not enough underlying tokens for stake");

        (bool approved, ) = token.call(abi.encodeWithSignature("approve(address,uint256)", address(c), amount));
        require(approved, "approve failed");

        uint256 supplyBefore = c.totalSupply();
        uint256 balanceBefore = c.balanceOf(address(this));

        c.stake(amount);

        uint256 supplyAfter = c.totalSupply();
        uint256 balanceAfter = c.balanceOf(address(this));

        assert(supplyAfter == supplyBefore + amount && balanceAfter == balanceBefore + amount);
    }

    receive() external payable {}
}

