contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address staker, uint256 amount) public payable {
        require(staker != address(0), "staker zero");
        require(amount > 0, "amount zero");

        // Pull the staking tokens from the test contract to c.
        // First, ensure the test contract has enough staking tokens to approve and transfer.
        // Since C only holds an IERC20 public stakingToken, use it via the public getter.
        IERC20 token = c.stakingToken();

        // Mint possibility is not guaranteed; instead the test contract must already hold tokens.
        // Use a safe transfer from the test to the staker so that stakeFor can pull from staker.
        // Actually stakeFor pulls from msg.sender, which is this contract.
        // So we must first approve c from this contract and ensure balance.
        // The test contract's initial token balance is external; require it.
        require(token.balanceOf(address(this)) >= amount, "test lacks tokens");

        // Approve c to spend tokens from the test contract.
        // SafeERC20 uses call under the hood; calling approve directly is safest.
        (bool okApprove, ) = address(token).call(abi.encodeWithSelector(token.approve.selector, address(c), amount));
        require(okApprove, "approve failed");

        // Record before-values after setup.
        uint256 totalBefore = c.totalSupply();
        uint256 stakerBalBefore = c.balanceOf(staker);

        // Stake for the staker.
        c.stakeFor(staker, amount);

        // Now withdraw all for the staker with claim = true, sent to staker.
        // For withdrawAll the caller must be the staker, but c will treat msg.sender as this test contract.
        // This means we cannot directly call withdrawAll as the staker. Instead use withdraw for amount.
        // Since the staker has exactly `amount`, withdrawing `amount` is equivalent to withdrawAll.
        c.withdraw(amount, true);

        // Read after-values.
        uint256 totalAfter = c.totalSupply();
        uint256 stakerBalAfter = c.balanceOf(staker);

        // General rule: after stake + full withdraw, total supply returns to its prior value,
        // staker's balance returns to its prior value, and the net supply change is zero.
        assert(totalAfter == totalBefore);
        assert(stakerBalAfter == stakerBalBefore);
    }

    receive() external payable {}
}

