contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 stakeAmount, uint256 withdrawAmount) public {
        // Precondition: we must stake something and then withdraw something valid
        require(stakeAmount > 0, "stake zero not allowed");
        require(withdrawAmount > 0, "withdraw zero not allowed");
        require(withdrawAmount <= stakeAmount, "withdraw more than staked");

        // The test contract must be able to transfer staking tokens into C.
        // We need a staking token; the caller (checker) must have approved and funded this contract.
        // Since C's stakingToken is a public getter, we can read it.
        IERC20 stakingToken = c.stakingToken();
        require(stakingToken.balanceOf(address(this)) >= stakeAmount, "not enough tokens");
        require(stakingToken.allowance(address(this), address(c)) >= stakeAmount, "not enough allowance");

        // Record initial total supply and staking token balance of C before any state change.
        uint256 totalSupplyBefore = c.totalSupply();
        uint256 cTokenBalanceBefore = stakingToken.balanceOf(address(c));

        // Stake tokens.
        c.stake(stakeAmount);

        // After staking, the staker's balance should equal the stake amount.
        uint256 balanceAfterStake = c.balanceOf(address(this));
        uint256 totalSupplyAfterStake = c.totalSupply();

        // Withdraw the requested amount (no claim of rewards).
        c.withdraw(withdrawAmount, false);

        // Final state.
        uint256 balanceAfterWithdraw = c.balanceOf(address(this));
        uint256 totalSupplyAfterWithdraw = c.totalSupply();
        uint256 cTokenBalanceAfterWithdraw = stakingToken.balanceOf(address(c));

        // The general rule:
        // 1. After staking, balanceOf(test) == stakeAmount.
        // 2. After withdrawing withdrawAmount, balanceOf(test) == stakeAmount - withdrawAmount.
        // 3. totalSupply decreases by exactly withdrawAmount.
        // 4. The contract's staking token balance decreases by exactly withdrawAmount
        //    (relative to after-stake balance), unless the token has transfer fees (not expected).
        // 5. totalSupply is consistent: totalSupplyAfterWithdraw == totalSupplyAfterStake - withdrawAmount.
        assert(
            balanceAfterStake == stakeAmount &&
            balanceAfterWithdraw == stakeAmount - withdrawAmount &&
            totalSupplyAfterWithdraw == totalSupplyAfterStake - withdrawAmount &&
            cTokenBalanceAfterWithdraw == cTokenBalanceBefore + stakeAmount - withdrawAmount
        );
    }

    receive() external payable {}
}

