contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 stakeAmount, uint256 withdrawAmount, bool claim) public {
        // Precondition: stakeAmount > 0 for stake to succeed
        require(stakeAmount > 0, "stake amount must be >0");

        // Record initial values
        uint256 initialTotalSupply = c.totalSupply();
        uint256 initialBalanceThis = c.balanceOf(address(this));
        uint256 initialActualBalance = c.stakingToken().balanceOf(address(c));

        // Stake
        c.stake(stakeAmount);

        // After stake, totalSupply should increase by stakeAmount and balanceOf(this) should increase by stakeAmount
        uint256 afterStakeTotalSupply = c.totalSupply();
        uint256 afterStakeBalanceThis = c.balanceOf(address(this));
        uint256 afterStakeActualBalance = c.stakingToken().balanceOf(address(c));

        assert(afterStakeTotalSupply == initialTotalSupply + stakeAmount);
        assert(afterStakeBalanceThis == initialBalanceThis + stakeAmount);
        assert(afterStakeActualBalance == initialActualBalance + stakeAmount);

        // Withdraw: only if withdrawAmount <= balance and > 0
        if (withdrawAmount > 0 && withdrawAmount <= afterStakeBalanceThis) {
            uint256 beforeWithdrawTotalSupply = c.totalSupply();
            uint256 beforeWithdrawBalanceThis = c.balanceOf(address(this));
            uint256 beforeWithdrawActualBalance = c.stakingToken().balanceOf(address(c));

            c.withdraw(withdrawAmount, claim);

            uint256 afterWithdrawTotalSupply = c.totalSupply();
            uint256 afterWithdrawBalanceThis = c.balanceOf(address(this));
            uint256 afterWithdrawActualBalance = c.stakingToken().balanceOf(address(c));

            assert(afterWithdrawTotalSupply == beforeWithdrawTotalSupply - withdrawAmount);
            assert(afterWithdrawBalanceThis == beforeWithdrawBalanceThis - withdrawAmount);
            assert(afterWithdrawActualBalance == beforeWithdrawActualBalance - withdrawAmount);
        }
    }

    receive() external payable {}
}

