contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 stakeAmount, uint256 withdrawAmount) public payable {
        require(stakeAmount > 0);
        require(withdrawAmount > 0 && withdrawAmount <= stakeAmount);

        c.stakeFor(address(this), stakeAmount);

        uint256 totalBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(address(this));

        require(balBefore >= withdrawAmount);

        bool reverted;
        try c.withdraw(withdrawAmount, false) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 totalAfter = c.totalSupply();
        uint256 balAfter = c.balanceOf(address(this));

        assert(!reverted && totalBefore - totalAfter == withdrawAmount && balBefore - balAfter == withdrawAmount);
    }
}

