contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 stakeAmount, uint256 withdrawAmount) public {
        // Precondition: both amounts are positive.
        require(stakeAmount > 0 && withdrawAmount > 0, "amounts must be positive");

        // The test contract must hold enough staking tokens to stake.
        IERC20 stakingToken = c.stakingToken();
        uint256 stakingBalanceBeforeStake = stakingToken.balanceOf(address(this));
        require(stakingBalanceBeforeStake >= stakeAmount, "insufficient staking tokens");

        // Setup: stake via a top-level call on c.
        c.stake(stakeAmount);

        // Read before-values.
        uint256 totalBefore = c.totalSupply();
        uint256 balanceBefore = c.balanceOf(address(this));
        uint256 contractTokenBalanceBefore = stakingToken.balanceOf(address(c));

        // Precondition on the rule: withdrawing at most our balance.
        // If withdrawAmount > balanceBefore, we skip to avoid revert; the rule
        // only applies when it is a valid withdrawal.
        bool validWithdrawal = withdrawAmount <= balanceBefore && withdrawAmount < totalBefore;
        bool reverted;
        if (validWithdrawal) {
            try c.withdraw(withdrawAmount, false) {
                reverted = false;
            } catch {
                reverted = true;
            }

            uint256 totalAfter = c.totalSupply();
            uint256 balanceAfter = c.balanceOf(address(this));
            uint256 contractTokenBalanceAfter = stakingToken.balanceOf(address(c));

            // General rule: a successful withdrawal of x reduces totalSupply,
            // the staker's balance, and c's staking-token balance by exactly x.
            assert(
                reverted ||
                (
                    totalAfter == totalBefore - withdrawAmount &&
                    balanceAfter == balanceBefore - withdrawAmount &&
                    contractTokenBalanceAfter == contractTokenBalanceBefore - withdrawAmount
                )
            );
        } else {
            // If not a valid withdrawal, the rule is trivially vacuously satisfied;
            // assert something that is always true.
            assert(totalBefore >= 0);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address rewardToken, uint256 stakeAmount, uint256 rewardAmount) public {
        require(stakeAmount > 0 && rewardAmount > 0, "amounts must be positive");

        IERC20 stakingToken = c.stakingToken();
        IERC20 rewardErc20 = IERC20(rewardToken);

        require(stakingToken.balanceOf(address(this)) >= stakeAmount, "insufficient staking tokens");
        require(rewardErc20.balanceOf(address(this)) >= rewardAmount, "insufficient reward tokens");

        c.addReward(rewardToken);

        c.stake(stakeAmount);

        c.setRewardDistributor(address(this));

        rewardErc20.approve(address(c), rewardAmount);
        c.notifyRewardAmount(rewardToken, rewardAmount);

        uint256 claimableBefore = c.claimableRewards(address(this), rewardToken);
        uint256 contractRewardBalanceBefore = rewardErc20.balanceOf(address(c));
        require(claimableBefore > 0, "no claimable reward to pay out");

        uint256 payerBalanceBefore = rewardErc20.balanceOf(address(this));

        bool reverted;
        try c.getReward(address(this), rewardToken) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 claimableAfter = c.claimableRewards(address(this), rewardToken);
        uint256 contractRewardBalanceAfter = rewardErc20.balanceOf(address(c));
        uint256 payerBalanceAfter = rewardErc20.balanceOf(address(this));

        assert(
            reverted ||
            (
                claimableAfter == 0 &&
                contractRewardBalanceAfter == contractRewardBalanceBefore - claimableBefore &&
                payerBalanceAfter == payerBalanceBefore + claimableBefore
            )
        );
    }

    receive() external payable {}
}

