contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 stakeAmount, uint256 withdrawAmount) public {
        require(stakeAmount > 0, "stake must be positive");
        require(stakeAmount <= 1e30, "stake too large");

        uint256 balanceBefore = c.balanceOf(address(this));
        uint256 supplyBefore = c.totalSupply();

        // Observe totalSupply and balanceOf consistency after staking.
        c.stake(stakeAmount);

        uint256 balanceAfterStake = c.balanceOf(address(this));
        uint256 supplyAfterStake = c.totalSupply();

        bool withdrew = false;
        bool reverted = false;

        if (withdrawAmount > 0 && withdrawAmount <= balanceAfterStake) {
            c.withdraw(withdrawAmount, false);
            withdrew = true;
        }

        uint256 balanceFinal = c.balanceOf(address(this));
        uint256 supplyFinal = c.totalSupply();

        // Staking increases totalSupply exactly by the staked amount and reports it via balanceOf.
        assert(balanceAfterStake == balanceBefore + stakeAmount);
        assert(supplyAfterStake == supplyBefore + stakeAmount);

        // After an optional withdrawal, accounting is consistent:
        // - totalSupply cannot exceed the amount staked in this test
        // - a state-changing withdrawal cannot create tokens (balance/supply must not increase)
        // - withdrawing reduces supply and balance by the withdrawn amount or leaves them unchanged
        assert(supplyFinal <= supplyBefore + stakeAmount);
        assert(balanceFinal <= supplyFinal);

        if (withdrew) {
            assert(supplyFinal == supplyAfterStake - withdrawAmount);
            assert(balanceFinal == balanceAfterStake - withdrawAmount);
        } else {
            assert(supplyFinal == supplyAfterStake);
            assert(balanceFinal == balanceAfterStake);
        }

        if (reverted) {
            assert(withdrawAmount == 0);
        }
    }

    receive() external payable {}
}

