contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 stakeAmount, uint256 withdrawAmount) public payable {
        uint256 beforeTotalSupply = c.totalSupply();
        uint256 beforeContractBalance = address(c).balance;

        require(stakeAmount > 0, "stake amount must be positive");

        address thisAddr = address(this);

        // Fund this contract with Ether so any payable path won't be blocked
        require(address(this).balance >= 0, "balance always ≥ 0");

        // Stake on behalf of this contract (this test contract is msg.sender for c, so it receives the stake)
        c.stakeFor(thisAddr, stakeAmount);

        uint256 afterStakeTotalSupply = c.totalSupply();

        // Rule: staking increases totalSupply by exactly the staked amount
        assert(afterStakeTotalSupply == beforeTotalSupply + stakeAmount);

        // Rule: totalSupply never exceeds the contract's actual balance of staking tokens
        // (totalSupply counts only tokens actually deposited into c)
        // We can observe staking token balance via the staking token's balanceOf on c
        uint256 contractStakingBalance = IERC20(c.stakingToken()).balanceOf(address(c));
        assert(afterStakeTotalSupply <= contractStakingBalance);

        // The Ether balance of c should never increase from staking (no Ether should be accepted by c)
        assert(address(c).balance <= beforeContractBalance);

        // Withdraw exactly what was staked (if withdrawAmount is within range)
        if (withdrawAmount <= c.balanceOf(thisAddr)) {
            c.withdraw(withdrawAmount, false);
            uint256 afterWithdrawTotalSupply = c.totalSupply();
            // Rule: totalSupply decreases by exactly the withdrawn amount
            assert(afterWithdrawTotalSupply == afterStakeTotalSupply - withdrawAmount);
        }
    }

    receive() external payable {}
}

