contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 stakeAmount, uint256 withdrawAmount) public {
        require(withdrawAmount > 0, "withdraw amount must be positive");
        require(stakeAmount > 0, "stake amount must be positive");

        uint256 supplyBefore = c.totalSupply();
        uint256 balanceBefore = c.balanceOf(address(this));

        c.stake(stakeAmount);

        uint256 supplyAfterStake = c.totalSupply();
        uint256 balanceAfterStake = c.balanceOf(address(this));

        require(balanceAfterStake >= balanceBefore + stakeAmount, "stake did not increase balance");
        require(supplyAfterStake >= supplyBefore + stakeAmount, "stake did not increase supply");

        bool reverted;
        if (withdrawAmount > balanceAfterStake) {
            try c.withdraw(withdrawAmount, false) { reverted = false; } catch { reverted = true; }
        } else {
            reverted = false;
        }

        if (withdrawAmount > balanceAfterStake) {
            assert(reverted && c.balanceOf(address(this)) == balanceAfterStake && c.totalSupply() == supplyAfterStake);
        } else {
            assert(c.balanceOf(address(this)) == balanceAfterStake - withdrawAmount && c.totalSupply() == supplyAfterStake - withdrawAmount);
        }
    }
}

